python3 - <<'EOF'
import copy
import lidar_scan
from lidar_scan import tiles as t
from lidar_scan import build_tile_pyramid, query_tile_window

assert lidar_scan.query_tile_window is t.query_tile_window
assert "query_tile_window" in lidar_scan.__all__

points = [(x + 0.5, y + 0.5, float(x + y), 1.0, 0.1)
          for x in range(0, 600, 20) for y in range(0, 600, 20)]
pyr = build_tile_pyramid(points, 1.0, 256, 3)

r = query_tile_window(pyr, 0, 200, 200, 300, 300)
assert r == tuple(x for x in pyr[0]
                  if x[4] >= 200 and x[2] <= 300 and x[5] >= 200 and x[3] <= 300)
assert all(len(x) == 9 for x in r)
assert query_tile_window(pyr, 0, 255, 255, 255, 255)[0] is pyr[0][0]
assert query_tile_window(pyr, 2, 10**6, 10**6, 10**6 + 1, 10**6 + 1) == ()
snap = copy.deepcopy(pyr)
query_tile_window(pyr, 1, -10**9, -10**9, 10**9, 10**9)
assert pyr == snap
assert query_tile_window(pyr, 0, 0, 0, 0, 0)[0] is pyr[0][0]

for bad in [[pyr], {}, "x", None, 1]:
    try: query_tile_window(bad, 0, 0, 0, 0, 0)
    except TypeError: pass
    else: raise AssertionError(("pyramid type", bad))

for kw in [dict(level=1.0), dict(ix_min=True), dict(iy_min=0.0),
           dict(ix_max=False), dict(iy_max="3")]:
    try: query_tile_window(pyr, **{**dict(level=0,ix_min=0,iy_min=0,ix_max=1,iy_max=1), **kw})
    except TypeError: pass
    else: raise AssertionError(("arg type", kw))
try:
    query_tile_window([], True, 0,0,0,0)
except TypeError: pass
else: raise AssertionError("precedence")

for lv in (-1, 3, 10):
    try: query_tile_window(pyr, lv, 0,0,1,1)
    except ValueError: pass
    else: raise AssertionError(("level", lv))

# inverted: ix_min>ix_max ; iy_min>iy_max (args order: ix_min,iy_min,ix_max,iy_max)
for b in [(1,0,0,0), (0,1,0,0)]:
    try: query_tile_window(pyr, 0, *b)
    except ValueError: pass
    else: raise AssertionError(("inverted", b))

good = pyr[0][0]
cases = [good[:8],                                  # wrong length
         good[:8] + (True,),                        # bool count
         (0.0,) + good[1:],                         # float tx
         good[:6] + (1.0, float("nan"), good[8]),   # nan zmax
         good[:6] + (1, 2, good[8]),                # int z
         tuple(sorted(pyr[0], key=lambda z:(-z[0],-z[1]))),  # unsorted
         pyr[0] + pyr[0][0:1],                      # duplicate
         good[:4] + (good[2]-1, good[5]) + good[6:],  # ix1 < ix0
         good[:5] + (good[3]-1,) + good[6:]]        # iy1 < iy0
for bad_tiles in cases:
    bad_pyr = (bad_tiles,) + pyr[1:]
    try:
        query_tile_window(bad_pyr, 0, -10**9,-10**9,10**9,10**9)
    except ValueError: pass
    else: raise AssertionError(("structure", bad_tiles))
try: query_tile_window((list(pyr[0]),), 0, 0,0,1,1)
except ValueError: pass
else: raise AssertionError("level tuple")

bad_pyr = pyr[:1] + (((good[0],good[1],0,0,-1,-1,1.0,2.0,1),),)
try: query_tile_window(bad_pyr, 0, 0,0,1,1)
except ValueError: pass
else: raise AssertionError("other-level bounds")

w = ((-1, -1, -300, -300, -300, -300, 1.0, 2.0, 3),)
assert query_tile_window((w,), 0, -300, -300, -300, -300) == w
assert query_tile_window((w,), 0, -299, -299, -1, -1) == ()
assert query_tile_window(((),()), 0, 0,0,1,1) == ()
print("ALL SMOKE CHECKS PASSED")
EOF
